layer.css:
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid color-mix(in srgb, var(--ryt-border) 6%, transparent); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: rgba(200, 200, 200, 0.1); border-top: 1px solid color-mix(in srgb, var(--ryt-border) 6%, transparent); border-right: 1px solid color-mix(in srgb, var(--ryt-border) 6%, transparent); border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 6%, transparent); border-left: 1px solid color-mix(in srgb, var(--ryt-border) 6%, transparent); border-radius: 6px; transition: 0.3s }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="header"] { border-bottom: 1px solid color-mix(in srgb, var(--ryt-border) 6%, transparent); border-top: none }
[data-ryt="button"] { color: rgb(118, 118, 118); background-color: var(--ryt-bg); border-top: 1px solid rgb(224, 224, 224); border-right: 1px solid rgb(224, 224, 224); border-bottom: 1px solid rgb(224, 224, 224); border-left: 1px solid rgb(224, 224, 224); border-radius: 6px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(118, 118, 118); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 14px; padding-bottom: 0px; padding-left: 14px; transition: border-color 0.15s, box-shadow 0.15s }
[data-ryt="review"] { color: color-mix(in srgb, var(--ryt-border) 70%, transparent); font-size: 14px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: color-mix(in srgb, var(--ryt-border) 70%, transparent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-size: 22.4px; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
article[data-ryt="rec-card"]:hover { transform: translateY(-0.5rem); box-shadow: 0 25px 50px -12px var(--ryt-border) }
